import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Use the Quickselect algorithm to find the k-th largest element in an unsorted list.
    Average time complexity: O(n), Worst-case time complexity: O(n^2).
    """
    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]  # Move pivot to end
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # To find the k-th largest, we use ">"
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[store_index], nums[right] = nums[right], nums[store_index]  # Move pivot to its final place
        return store_index

    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:
            return nums[left]  # Only one element left
        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)
        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Use the Introselect algorithm, which combines Quickselect and Heapselect to find the k-th largest element in an unsorted list.
    Average time complexity: O(n), Worst-case time complexity: O(n log n).
    """
    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[store_index], nums[right] = nums[right], nums[store_index]
        return store_index

    def introselect(left: int, right: int, k: int, depth_limit: int) -> int:
        if left == right:
            return nums[left]
        if depth_limit == 0:
            return sorted(nums[left:right + 1])[k - left]  # Fallback to sorting if depth limit reached

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return introselect(left, pivot_index - 1, k, depth_limit - 1)
        else:
            return introselect(pivot_index + 1, right, k, depth_limit - 1)

    if k < 1 or k > len(nums):
        raise ValueError("k must be between 1 and the number of elements in nums")

    return introselect(0, len(nums) - 1, k - 1, 2 * (len(nums).bit_length()))
